<script lang="ts">import {goto} from '$app/navigation';import {createInstance,getSnapshot,command} from '$lib/api';let busy=false;let error='';async function start(){busy=true;try{const made=await createInstance();const token=made.control_url.split('/').pop()!;const snap=await getSnapshot('control',token);await command(token,snap.clocks[0].id,'start');await goto(made.control_url)}catch(e){error=(e as Error).message;busy=false}}</script>
<svelte:head><title>Chronograph — Shared time, instantly</title><meta name="description" content="A server-synchronized stopwatch and timer you can share instantly."/></svelte:head>
<main class="landing"><div class="landing-mark">C/</div><p class="eyebrow">CLOUD-SYNCHRONIZED TIME</p><div class="preview">00:00.00</div><h1>OPEN.<br/>START.<br/>SHARE.</h1><button class="launch" disabled={busy} on:click={start}>{busy?'CONNECTING…':'START NOW'}</button>{#if error}<p role="alert">{error}</p>{/if}<p class="promise">NO ACCOUNT · NO SETUP · SERVER TIME</p></main>
